function toStr( o )
{
  let self = this;
  return self.exportString( _.mapOnly_( null, o || Object.create( null ), self.exportString.defaults ) );
}

//

function toString( o )
{
  let self = this;
  return self.exportString( _.mapOnly_( null, o || Object.create( null ), self.exportString.defaults ) );
}

//

function _inspectCustom()
{
  let self = this;
  return self.exportString();
}

//

function _toPrimitive()
{
  let self = this;
  return self.exportString();
}

