  if( _.countable.is( key ) )
  {
    if( _.argumentsArray.like( key ) )
    for( let s = 0 ; s < key.length ; s++ )
    set( dstMap, key[ s ], val );
    else
    for( let value of key )
    set( dstMap, value, val );
