 * @method stripRight
 * @namespace Tools
 *
 */

function stripRight( o )
{

  if( _.strIs( o ) || _.arrayIs( o ) )
  o = { src : o };

  _.routine.options( stripRight, o );
  _.assert( arguments.length === 1, 'Expects single argument' );

  return _.strStrip( o );
}

stripRight.defaults =
{
  ... strip.defaults,
  stripper : /(\s|\n|\0)+$/gm,
}

