function pathResolveLinkTailChain_head()
{
  let self = this;
  let path = self.system ? self.system.path : self.path;;
  let o = self._preFilePathScalarWithProviderDefaults.apply( self, arguments );

  _.assert( path.isAbsolute( o.filePath ) );

  if( o.found === null )
  o.found = [];

  if( o.result === null )
  o.result = [ o.filePath ];

  return o;
