    }
    catch( err )
    {

      self.logger.log( '-' );
      self.logger.error( 'JSON:' );
      self.logger.error( _.entity.exportString( o.data, { levels : 999 } ) );
      self.logger.log( '-' );
      throw _.err( 'Cant convert JSON\n', err );
    }
  }

  /* write */

  // delete o.prefix;
  // delete o.pretty;
  // delete o.jsLike;
  // delete o.cloning;

  let o2 = _.mapOnly_( null, o, self.fileWrite.defaults );

