        !!self.FindOutputFormat[ o.outputFormat ],
        () => 'Unknown output format ' + _.entity.exportStringDiagnosticShallow( o.outputFormat )
        + '\nKnown output formats : ' + _.entity.exportString( _.props.keys( self.FindOutputFormat ) )
      );
    }

  }

