  function writeDstDown2( record )
  {

    if( o.onWriteDstDown )
    {
      let onr = o.onWriteDstDown.call( self, record, o );
      _.assert( _.boolsAllAre( onr ) );
      onr = _.all( onr, ( e ) => e === _.dont ? false : e );
      _.assert( _.boolIs( onr ) );
      return onr;
    }

    return true;
  }

