  function writeSrcUp( record )
  {

    if( o.onWriteSrcUp )
    {
      let onr = o.onWriteSrcUp.call( self, record, o );
      _.assert( _.boolsAllAre( onr ) );
      onr = _.all( onr, ( e ) => e === _.dont ? false : e );
      _.assert( _.boolIs( onr ) );
      return onr
    }

