    return true;
    // if( !onr )
    // return onr;
    // return onr;
  }

  /* */

  function writeSrcDown( record )
  {

    srcDeleteMaybe( record );

    if( o.onWriteSrcDown )
    {
      let onr = o.onWriteSrcDown.call( self, record, o );
      _.assert( _.boolsAllAre( onr ) );
      onr = _.all( onr, ( e ) => e === _.dont ? false : e );
      _.assert( _.boolIs( onr ) );
