    if( record.dst.absolute === record.src.absolute )
    return;

    let r = record.dst.factory.effectiveProvider.fileDelete( record.dst.absolute );
    record.performed = r;
    /* qqq : should be in v >= 3 log as : " - deleted ..." */

  }

