      }
    }
    else
    {
      _.assert( record.action === 'fileCopy' || record.action === 'hardLink' || record.action === 'softLink' || record.action === 'textLink' || record.action === 'nop' );
      record.src.factory.effectiveProvider.fileDelete( record.src.absolute );
    }

  }

