    dstDir[ dstName ] = srcDir[ srcName ];
    delete srcDir[ srcName ];

    self.extraStats[ o.dstPath ] = self.extraStats[ o.srcPath ];
    delete self.extraStats[ o.srcPath ];

    if( dstDir !== srcDir )
