  let srcPath = o.srcPath;

  con.then( checkPaths )

  if( o.context )
  {
    con.then( () => o.context.tempRenameMaybe() )
    con.then( handleHardlinkBreaking );
  }

  con.then( link );

  if( o.context )
  {
    con.then( tempDelete );
    con.finally( tempRenameRevert );
