function dirReadAct( o )
{
  let self = this;
  let result = null;

  _.routine.assertOptions( dirReadAct, arguments );

  let nativizedFilePath = self.path.nativize( o.filePath );

  /* read dir */

  if( o.sync )
  {
    try
    {
      let stat = self.statReadAct
      ({
        filePath : o.filePath,
        throwing : 1,
        sync : 1,
        resolvingSoftLink : 1,
      });
      if( stat.isDir() )
      {
        result = File.readdirSync( nativizedFilePath );
        return result
      }
      else
      {
        result = self.path.name({ path : o.filePath, full : 1 });
      }
    }
    catch( err )
    {
      throw _.err( err );
      result = null;
    }

    return result;
  }
  else
  {
    let con = new _.Consequence();

    self.statReadAct
    ({
      filePath : o.filePath,
      sync : 0,
      resolvingSoftLink : 1,
      throwing : 1,
    })
    .give( function( err, stat )
    {
      if( err )
      {
        con.error( _.err( err ) );
      }
      else if( stat.isDir() )
      {
        File.readdir( nativizedFilePath, function( err, files )
        {
          if( err )
          {
            con.error( _.err( err ) );
          }
          else
          {
            con.take( files || null );
          }
        });
      }
      else
      {
        result = self.path.name({ path : o.filePath, full : 1 });
        con.take( result );
      }
    });

    return con;
  }

}

_.routineExtend( dirReadAct, Parent.prototype.dirReadAct );

