function ignoreRemove( o )
{
  let provider = _.fileProvider;
  let path = _.git.path;
  // let path = provider.path;

  if( arguments.length === 2 )
  o = { insidePath : arguments[ 0 ], pathMap : arguments[ 1 ] }

  _.assert( arguments.length === 1 || arguments.length === 2 );
  _.routine.options_( ignoreRemove, o );

  let gitignorePath = path.join( o.insidePath, '.gitignore' );

  if( !provider.fileExists( gitignorePath ) )
  throw _.err( 'Provided .gitignore file doesn`t exist at:', _.strQuote( gitignorePath ) );

  if( !this.isTerminal( o.insidePath ) )
  throw _.err( 'Provided .gitignore file:', _.strQuote( gitignorePath ), 'is not terminal' );

  let records = _.props.keys( o.pathMap );

  if( !records.length )
  return false;

  let gitconfig = provider.fileRead( gitignorePath );
  gitconfig = _.strSplitNonPreserving({ src : gitconfig, delimeter : '\n' })

  let result = 0;

  if( !gitconfig.length )
  return result;

  result = _.arrayRemovedArrayOnce( gitconfig, records );

  let data = gitconfig.join( '\n' );
  provider.fileWrite({ filePath : gitignorePath, data, writeMode : 'rewrite' });

  return result;
}

_.routineExtend( ignoreRemove, ignoreAdd );

//

function ignoreRemoveAll( o )
{
  let provider = _.fileProvider;
  let path = _.git.path;
  // let path = provider.path;

  if( !_.object.isBasic( o ) )
  o = { insidePath : arguments[ 0 ] }

  _.assert( arguments.length === 1 || arguments.length === 2 );
  _.routine.options_( ignoreRemoveAll, o );

  let gitignorePath = path.join( o.insidePath, '.gitignore' );
  if( !provider.fileExists( gitignorePath ) )
  return false;
  provider.fileDelete( gitignorePath );
  return true;
}

var defaults = ignoreRemoveAll.defaults = Object.create( null );
defaults.insidePath = null;

// --
// maker
// --

function repositoryInit( o )
{
  let self = this;
  let ready = _.take( null );

  o = _.routine.options_( repositoryInit, o );

  let nativeRemotePath = null;
  let parsed = null;
  let remoteExists = null;

  _.assert( !o.remote || _.strDefined( o.remotePath ), `Expects path to remote repository {-o.remotePath-}, but got ${_.color.strFormat( String( o.remotePath ), 'path' )}` )

  if( o.remotePath )
  {
    o.remotePath = nativeRemotePath = _.git.path.nativize( o.remotePath );

    parsed = _.git.path.parse({ remotePath : o.remotePath, full : 0, atomic : 0, objects : 1 });
    remoteExists = self.isRepository({ remotePath : o.remotePath, sync : 1 });
  }

  if( o.remote === null )
  o.remote = !!o.remotePath;
  if( o.local === null )
  o.local = !!o.localPath;

  let start = _.process.starter
  ({
    logger : _.logger.relativeMaybe( o.logger, -1 ),
    verbosity : o.logger ? o.logger.verbosity - 1 : 0,
    sync : 0,
    deasync : 0,
    outputCollecting : 1,
    mode : 'spawn',
    currentPath : o.localPath,
  });

  if( o.remote && !remoteExists )
  ready.then( () => remoteInit() );
  if( o.local )
  ready.then( () => localInit() );

  ready.finally( ( err, arg ) =>
  {
    if( err )
    {
      _.error.attend( err );
      if( o.throwing )
      throw _.err( err, `\nFailed to init git repository remotePath:${_.color.strFormat( String( o.remotePath ), 'path' )}` );
      return null;
    }
    return arg;
  });

  if( o.sync )
  {
    ready.deasync();
    return ready.sync();
  }

  return ready;

  /* */

  function remoteInit()
  {
    if( o.logger && o.logger.verbosity > 0 )
    o.logger.log( `Making remote repository ${_.color.strFormat( String( o.remotePath ), 'path' )}` );

    if( o.dry )
    return true;

    const o2 = _.mapOnly_( null, o, _.repo.repositoryInit.defaults );
    return _.repo.repositoryInit( o2 )
  }

  /* */

  function localInit()
  {
    _.assert( _.git.path.is( o.localPath ) && !_.git.path.isGlobal( o.localPath ), () => `Expects local path, but got ${_.color.strFormat( String( o.localPath ), 'path' )}` );

    o.localPath = _.git.path.canonize( o.localPath );

    if( _.fileProvider.fileExists( o.localPath ) && !_.fileProvider.isDir( o.localPath ) )
    throw _.err( `Can't clone repository to ${_.color.strFormat( String( o.localPath ), 'path' )}. It is occupied by non-directory.` );

    if( o.remotePath && remoteExists )
    {

      if( self.isRepository({ localPath : o.localPath }) )
      return localRepositoryRemoteAdd();
      else
      return localRepositoryClone();

    }
    else
    {

      if( self.isRepository({ localPath : o.localPath }) )
      return localRepositoryRemoteAdd();
      else
      return localRepositoryNew();

    }
  }

  /* */

  function localRepositoryNew()
  {
    if( o.logger && o.logger.verbosity > 0 )
    o.logger.log( `Making a new local repository at ${_.color.strFormat( String( o.localPath ), 'path' )}` );
    if( o.dry )
    return null;
    _.fileProvider.dirMake( o.localPath );
    start( `git init .` );
    return start( `git remote add origin ${nativeRemotePath}` );
  }

  /* */

  function localRepositoryRemoteAdd()
  {
    let wasRemotePath = _.git.remotePathFromLocal( o.localPath );
    if( wasRemotePath )
    {
      if( wasRemotePath !== o.remotePath )
      throw _.err( `Repository at ${o.localPath} already exists, but has different origin ${wasRemotePath}` );
      return null;
    }
    if( o.logger )
    o.logger.log( `Adding origin ${_.color.strFormat( String( o.remotePath ), 'path' )} to local repository ${_.color.strFormat( String( o.localPath ), 'path' )}` );
    if( o.dry )
    return null;
    return start( `git remote add origin ${nativeRemotePath}` );
  }

  /* */

  function localRepositoryClone()
  {

    if( o.logger && o.logger.verbosity > 0 )
    if( _.fileProvider.isDir( o.localPath ) )
    o.logger.log( `Directory ${_.color.strFormat( String( o.localPath ), 'path' )} will be moved` );

    if( o.logger && o.logger.verbosity > 0 )
    o.logger.log( `Cloning repository from ${_.color.strFormat( String( o.remotePath ), 'path' )} to ${_.color.strFormat( String( o.localPath ), 'path' )}` );

    if( o.dry )
    return null;

    let downloadPath = o.localPath;
    if( _.fileProvider.isDir( o.localPath ) )
    {
      downloadPath = _.git.path.join( o.localPath + '-' + _.idWithGuid() );
    }

    _.fileProvider.dirMake( downloadPath );

    let start = _.process.starter
    ({
      logger : _.logger.relativeMaybe( o.logger, -1 ),
      verbosity : o.logger ? o.logger.verbosity - 1 : 0,
      sync : 0,
      deasync : 0,
      outputCollecting : 1,
      mode : 'spawn',
      currentPath : downloadPath,
    });

    return start( `git clone ${nativeRemotePath} .` )
    .finally( ( err, arg ) =>
    {
      if( err )
      {
        _.fileProvider.filesDelete( downloadPath );
        if( err )
        throw _.err( err );
      }
      try
      {
        let o2 =
        {
          dst : o.localPath,
          src : downloadPath,
          dstRewriting : 1,
          dstRewritingOnlyPreserving : 1,
          linkingAction : 'hardLink',
        }
        _.fileProvider.filesReflect( o2 );
      }
      catch( err )
      {
        _.fileProvider.filesDelete( downloadPath );
        throw _.err( err, `\nCollision of local files with remote files at ${_.color.strFormat( String( o.localPath ), 'path' )}` );
      }
      _.fileProvider.filesDelete( downloadPath );
      return arg;
    });

  }
}

repositoryInit.defaults =
{
  remotePath : null,
  localPath : null,
  remote : null,
  local : null,
  throwing : 1,
  sync : 0,
  logger : 0,
  dry : 0,
  description : null,
  token : null,
};

//

function repositoryDelete( o )
{
  o = _.routine.options_( repositoryDelete, o );

  let ready = _.take( null );
  let parsed = '';

  if( o.remotePath )
  {
    o.remotePath = _.git.path.normalize( o.remotePath );
    parsed = _.git.path.parse({ remotePath : o.remotePath, full : 0, atomic : 0, objects : 1 });
  }

  if( o.remote === null )
  o.remote = !!o.remotePath;
  if( o.local === null )
  o.local = !!o.localPath;

  if( o.local )
  ready.then( () => removeLocal() );
  if( o.remote )
  ready.then( () => removeRemote() );

  ready.finally( ( err, arg ) =>
  {
    if( err )
    {
      if( o.throwing )
      throw _.err( err, `\nFailed to delete repository : ${_.color.strFormat( String( o.remotePath ), 'path' )}` );
      _.error.attend( err );
    }
    return arg || false;
  });

  if( o.sync )
  {
    ready.deasync();
    return ready.sync();
  }

  return ready;

  /* */

  function removeRemote()
  {
    _.assert( false, 'not implemented' );
  }

  /* */

  function removeRemote()
  {
    if( o.logger && o.logger.verbosity > 0 )
    o.logger.log( `Deleting remote repository ${_.color.strFormat( String( o.remotePath ), 'path' )}` );

    if( o.dry )
    return true;

    let o2 = _.mapOnly_( null, o, _.repo.repositoryDelete.defaults );
    return _.retry
    ({
      routine : () => _.repo.repositoryDelete( o2 ),
      attemptLimit : o.attemptLimit,
      attemptDelay : o.attemptDelay,
      attemptDelayMultiplier : o.attemptDelayMultiplier,
      defaults : _.remote.attemptDefaults,
    });
  }
}

repositoryDelete.defaults =
{
  remotePath : null,
  localPath : null,
  local : null,
  remote : null,
  token : null,
  throwing : 1,
  sync : 0,
  logger : 1,
  dry : 0,
  attemptLimit : null,
  attemptDelay : null,
  attemptDelayMultiplier : null,
};

//

function repositoryClone( o )
{
  let localProvider = _.fileProvider;

  _.assert( arguments.length === 1, 'Expects single argument' );
  _.routine.options_( repositoryClone, o );
  _.assert( _.strDefined( o.localPath ), 'Expects local path' );
  _.assert( _.strDefined( o.remotePath ) || _.mapIs( o.remotePath ), 'Expects remote path' );

  let ready = _.take( null );

  if( _.git.isRepository({ localPath : o.localPath }) )
  return ready;

  let parsed = _.git.path.parse({ remotePath : o.remotePath, full : 1, atomic : 0 });
  let remoteVcsPathParsed = _.mapBut_( null, parsed, { localVcsPath : null, tag : null, hash : null, query : null } );
  remoteVcsPathParsed.longPath = _.strRemoveEnd( parsed.longPath, '/' );
  let remoteVcsLongerPath = _.git.path.str( remoteVcsPathParsed );
  remoteVcsLongerPath = _.git.path.nativize( remoteVcsLongerPath );

  if( localProvider.fileExists( o.localPath ) )
  _.sure( localProvider.dirIsEmpty( o.localPath ) );
  else
  localProvider.dirMake( o.localPath );

  const logger = _.logger.relativeMaybe( o.logger, -1 );
  const shell = _.process.starter
  ({
    logger,
    verbosity : o.logger ? o.logger.verbosity - 1 : 0,
    currentPath : o.localPath,
    ready,
  });

  ready = _.retry
  ({
    routine : () => shell( `git clone ${ remoteVcsLongerPath } . --config core.autocrlf=false` ),
    attemptLimit : o.attemptLimit,
    attemptDelay : o.attemptDelay,
    attemptDelayMultiplier : o.attemptDelayMultiplier,
    defaults : _.remote.attemptDefaults,
    onError,
    logger,
  });

  if( o.sync )
  {
    ready.deasync();
    return ready.sync();
  }

  return ready;

  /* */

  function onError( err )
  {
    const errorMsgs =
    [
      'Could not resolve host',
      'Could not read from remote repository',
      'Failed to connect',
      'returned error: 429',
      'expected flush after ref listing',
    ];
    if( !_.strHasAny( err.originalMessage, errorMsgs ) )
    return false;

    _.error.attend( err );
    return true;
  }
}

repositoryClone.defaults =
{
  remotePath : null,
  localPath : null,
  logger : 0,
  sync : 0,
  attemptLimit : null,
  attemptDelay : null,
  attemptDelayMultiplier : null,
};

//

function repositoryCheckout( o )
{
  let localProvider = _.fileProvider;

  _.assert( arguments.length === 1, 'Expects single argument' );
  _.routine.options_( repositoryCheckout, o );
  _.assert( _.strDefined( o.localPath ), 'Expects local path' );
  _.assert( _.strDefined( o.remotePath ) || _.mapIs( o.remotePath ), 'Expects remote path' );

  let ready = _.take( null );
  // let parsed = _.git.pathParse( o.remotePath );

  let parsed = _.git.path.parse({ remotePath : o.remotePath, full : 1, atomic : 0 });

  let shell = _.process.starter
  ({
    // verbosity : o.verbosity,
    logger : _.logger.relativeMaybe( o.logger, -1 ),
    verbosity : o.logger ? o.logger.verbosity - 1 : 0,
    currentPath : o.localPath,
    outputCollecting : 1,
    ready,
  });

  if( parsed.tag )
  ready.then( () =>
  {
    let repoHasTag = _.git.repositoryHasTag
    ({
      localPath : o.localPath,
      remotePath : parsed,
      tag : parsed.tag
    });

    if( !repoHasTag )
    {
      let remoteVcsPathParsed = _.mapBut_( null, parsed, { tag : null, hash : null, query : null } );
      let remoteVcsPath = _.git.path.str( remoteVcsPathParsed );
      remoteVcsPath = _.git.path.nativize( remoteVcsPath );
      throw _.err
      (
        `Specified tag: ${_.strQuote( parsed.tag )} doesn't exist in local and remote copy of the repository.\
        \nLocal path: ${_.color.strFormat( String( o.localPath ), 'path' )}\
        \nRemote path: ${_.color.strFormat( String( remoteVcsPath ), 'path' )}`
      );
    }

    return null;
  });

  let checkoutOptions =
  {
    execPath : 'git -c "core.autocrlf=false" checkout ' + ( parsed.hash || parsed.tag )
  }

  shell( checkoutOptions )

  ready.catch( ( err ) =>
  {
    _.errAttend( err );
    if( o.localChanges && o.stashing )
    shell
    ({
      execPath : 'git -c "core.autocrlf=false" stash pop',
      sync : 1,
      deasync : 0,
      throwingExitCode : 0,
      ready : null
    })

    if( !_.strHasAny( checkoutOptions.output, [ 'fatal: reference', 'error: pathspec' ] ) )
    throw _.err( err );

    err = _.err
    (
      'Failed to checkout, branch/commit: '
      + _.strQuote( parsed.hash || parsed.tag )
      + ' doesn\'t exist in repository at '
      + _.strQuote( o.localPath )
    );
    err.reason = 'git';
    throw err;
  })

  if( o.sync )
  {
    ready.deasync();
    return ready.sync();
  }

  return ready;
}

repositoryCheckout.defaults =
{
  remotePath : null,
  localPath : null,
  logger : 0,
  sync : 0
};

//

function repositoryStash( o )
{
  _.routine.options_( repositoryStash, o );
  _.assert( arguments.length === 1, 'Expects single argument' );
  _.assert( _.strDefined( o.localPath ), 'Expects local path' );

  let ready = _.take( null );
  let shell = _.process.starter
  ({
    // verbosity : o.verbosity,
    logger : _.logger.relativeMaybe( o.logger, -1 ),
    verbosity : o.logger ? o.logger.verbosity - 1 : 0,
    currentPath : o.localPath,
    outputCollecting : 1,
    ready,
  });

  let shellOptions = { execPath : `git -c "core.autocrlf=false" stash ${ o.pop ? 'pop' : '' }` }

  shell( shellOptions );

  ready.catch( ( err ) =>
  {
    if( !_.strHas( shellOptions.output, 'CONFLICT' ) )
    throw _.err( err );
    _.errAttend( err );
    err = _.err( 'Automatic merge of stashed changes failed in repository at ' + _.strQuote( o.localPath ) + '. Fix conflict(s) manually.' );
    err.reason = 'git';
    throw err;
  })

  if( o.sync )
  {
    ready.deasync();
    return ready.sync();
  }

  return ready;
}

repositoryStash.defaults =
{
  localPath : null,
  // verbosity : null,
  logger : 0,
  pop : 0
};

//

function repositoryMerge( o )
{
  _.routine.options_( repositoryMerge, o );
  _.assert( arguments.length === 1, 'Expects single argument' );
  _.assert( _.strDefined( o.localPath ), 'Expects local path' );

  let ready = _.take( null );
  let shell = _.process.starter
  ({
    // verbosity : o.verbosity,
    logger : _.logger.relativeMaybe( o.logger, -1 ),
    verbosity : o.logger ? o.logger.verbosity - 1 : 0,
    currentPath : o.localPath,
    outputCollecting : 1,
    ready,
  });

  let shellOptions =
  {
    execPath : `git -c "merge.defaultToUpstream=true" -c "core.autocrlf=false" merge`
  }

  shell( shellOptions );

  ready.catch( ( err ) =>
  {
    if( !_.strHas( shellOptions.output, 'CONFLICT' ) )
    throw _.err( err )
    _.errAttend( err );
    err = _.err( 'Automatic merge of remote-tracking branch failed in repository at ' + _.strQuote( o.localPath ) + '. Fix conflict(s) manually.' );
    err.reason = 'git';
    throw err;
  })

  if( o.sync )
  {
    ready.deasync();
    return ready.sync();
  }

  return ready;
}

repositoryMerge.defaults =
{
  localPath : null,
  logger : 0,
};

//

function _tagStrip( src )
{
  const parsed = _.git.path.parse( src );
  delete parsed.tag;
  return _.git.path.str( parsed );
}

//

function _statusLocalGet( localPath )
{
  return _.git.statusLocal
  ({
    localPath,
    unpushedCommits : 0,
    unpushedTags : 0,
    unpushedBranches : 0,
    explaining : 1,
    detailing : 1,
    sync : 0,
  });
}


//

function _subrepositoryInitMaybe( dstBasePath, basePath )
{
  dstBasePath = _.git.path.normalize( dstBasePath );
  const parsed = _.git.path.parse( basePath );

  _.assert
  (
    _.str.begins( parsed.longPath, _.git.path.detrail( _.git.path.parse( dstBasePath ).longPath ) ),
    '{-o.dstDirPath-} should be a subdirectory of {-o.dstBasePath-}.'
  );

  if( !_.fileProvider.fileExists( basePath ) )
  _.fileProvider.dirMake( basePath );

  const isSubrepository = _.git.isRepository({ localPath : basePath });

  const con = _.take( null );
  if( !isSubrepository )
  {
    con.then( () =>
    {
      return _.git.repositoryInit
      ({
        localPath : basePath,
        remote : 0,
        local : 1,
      });
    });

    con.then( () => _statusLocalGet( basePath ) );
    con.then( ( status ) =>
    {
      const shell = _.process.starter
      ({
        logger,
        currentPath : basePath,
        inputMirroring : 0,
        outputCollecting : 0,
      });
      if( status.uncommitted )
      shell( 'git add .' );
      shell({ execPath : 'git commit --allow-empty -m Init' })
      return shell({ execPath : 'git commit --allow-empty -m "Indexed"' })
    });
  }

  return con.then( () => isSubrepository );
}

//

function _branchFromPath( basePath, path, local )
{
  const parsed = _.git.path.parse( path );
  if( parsed.tag )
  {
    const tagDescriptor = _.git.tagExplain
    ({
      remotePath : path,
      localPath : basePath,
      tag : parsed.tag,
      remote : !local,
      local,
    });

    if
    (
      tagDescriptor.isBranch
      && ( _.str.has( path, _.git.path.tagToken ) || !_.longHasAny( parsed.protocols, [ 'hd', 'file' ] ) )
    )
    return parsed.tag;
  }
  return null;
}

//

function _remoteNameGenerate( basePath )
{
  let remoteName = `_temp-${ _.idWithGuid() }`;
  const config = _.git.configRead( basePath );
  while( `remote "${ remoteName }"` in config )
  remoteName = `_temp-${ _.idWithGuid() }`;
  return remoteName;
}

//

function repositoryAgree( o )
{
  _.routine.options_( repositoryAgree, o );
  _.assert( arguments.length === 1, 'Expects single argument' );
  _.assert( _.str.defined( o.dstBasePath ), 'Expects local path to destination repository {-o.dstBasePath-}.' );
  _.assert( _.str.defined( o.srcBasePath ) || _.aux.is( o.srcBasePath ), 'Expects path to source repository {-o.srcBasePath-}.' );
  _.assert( _.str.is( o.commitMessage ) || o.commitMessage === null, 'Expects string with commit message {-o.commitMessage-}' );
  _.assert( _.longHasAny( [ 'src', 'dst', 'manual' ], o.mergeStrategy ) );

  /* */

  let error = null;
  const ready = _.take( null );

  let basePath = o.dstBasePath;
  o.dstBasePath = _tagStrip( basePath );
  if( o.dstDirPath )
  basePath = _.git.path.join( o.dstBasePath, o.dstDirPath );
  basePath = _.git.path.detrail( _tagStrip( basePath ) );
  let shouldRemove = false;

  const logger = _.logger.relativeMaybe( o.logger, -1 );
  const shell = _.process.starter
  ({
    logger,
    currentPath : basePath,
    inputMirroring : 0,
    outputCollecting : 0,
  });

  if( basePath !== o.dstBasePath )
  {
    ready.then( () => _subrepositoryInitMaybe( o.dstBasePath, basePath ) );
    ready.then( ( isSubrepository ) => shouldRemove = !isSubrepository );
  }
  ready.then( () =>
  {
    if( !o.dstBranch )
    o.dstBranch = _branchFromPath( basePath, o.dstBasePath, true ) || _.git.tagLocalRetrive({ localPath : basePath });
    _.sure
    (
      _.str.defined( o.dstBranch ),
      'Expects defined branch in destination repository. Provide it by option {-o.dstBranch-} or in path.'
    );
    return null;
  });

  const normalized = _.git.path.normalize( o.srcBasePath );
  const srcBasePath = _.git.path.nativize( normalized );
  const srcBasePathIsRepository = _.git.isRepository({ remotePath : normalized });

  let srcState = o.srcState;
  if( o.srcState )
  srcState = _.git._stateParse( o.srcState ).value;

  let remoteName, srcBranch;
  let tempPath = _.fileProvider.path.tempOpen();
  ready.then( () => _remoteNameGenerate( basePath ) )
  ready.then( ( name ) => { remoteName = name; return null });
  ready.then( () => shell( `git remote add ${ remoteName } ${ tempPath }` ) );
  srcRepositoryPrepare();
  ready.then( () =>
  {
    if( srcBasePathIsRepository )
    srcBranch = _branchFromPath( basePath, normalized, false ) || _.git.tagLocalRetrive({ localPath : tempPath });
    else
    srcBranch = 'master';
    return null;
  });

  /* */

  ready.then( () => _.git.tagLocalChange({ localPath : o.dstBasePath, tag : o.dstBranch }) );
  ready.then( () => shell({ execPath : `git fetch ${ remoteName }`, outputPiping : 0 }) );

  if( logger )
  ready.then( () =>
  {
    logger.log( 'Files that will be merged :' );
    return shell
    ({
      execPath : `git diff --name-only ${ o.dstBranch }..${ remoteName }/${ srcBranch }`,
      outputCollecting : 1
    });
  });
  if( !o.dry )
  {
    ready.then( () =>
    {
      let strategy = '-s recursive';
      if( o.mergeStrategy !== 'manual' )
      strategy += ` -X ${ o.mergeStrategy === 'src' ? 'theirs' : 'ours' }`;
      const mergeBranch = `${ remoteName }/${ srcBranch }`;

      return shell
      ({
        execPath : `git merge ${ strategy } --allow-unrelated-histories --squash ${ mergeBranch } ${ o.dstBranch }`,
        outputPiping : 0,
      });
    });

    ready.then( () => _statusLocalGet( basePath ) );
    ready.then( ( status ) =>
    {
      if( status.uncommitted )
      {
        let uncommittedFiles = filesFilter( status.uncommitted );
        if( shouldRemove )
        _.fileProvider.filesDelete( _.git.path.join( basePath, '.git' ) );

        if( !o.commitMessage )
        o.commitMessage = `Merge branch '${ srcBranch }' of ${ srcBasePath } into ${ o.dstBranch }`;

        if( uncommittedFiles === undefined || uncommittedFiles.length )
        {
          const srcHeadDescriptorCon = _.git.repositoryHistoryToJson
          ({
            localPath : tempPath,
            state1 : '#HEAD',
            state2 : '#HEAD',
          });
          const dstHeadDescriptorCon = _.git.repositoryHistoryToJson
          ({
            localPath : o.dstBasePath,
            state1 : '#HEAD',
            state2 : '#HEAD',
          });
          return _.Consequence.And( srcHeadDescriptorCon, dstHeadDescriptorCon );
        }
      }
      return null;
    });
    ready.then( ( descriptors ) =>
    {
      if( descriptors )
      {
        const onDate = _.git._onDate_functor({ relative : o.relative, delta : o.delta || 0 });
        let date = onDate( descriptors[ 0 ][ 0 ].date );

        const srcHeadDate = Date.parse( date );
        const dstHeadDate = Date.parse( descriptors[ 1 ][ 0 ].date );

        _.sure( srcHeadDate > dstHeadDate, 'The new commit should be newer than the last one.' );

        process.env.GIT_COMMITTER_DATE = date;
        date = `--date="${ date }"`;
        shell({ currentPath : o.dstBasePath, execPath : 'git add .' });
        return shell
        ({
          currentPath : o.dstBasePath,
          execPath : `git commit -m "${ o.commitMessage }" ${ date }`,
          outputPiping : 0,
        });
      }
      return null;
    });
  }
  ready.finally( ( err, arg ) =>
  {
    if( err )
    error = err;
    _.fileProvider.path.tempClose( tempPath );
    delete process.env.GIT_COMMITTER_DATE;

    if( !shouldRemove )
    return shell( `git remote remove ${ remoteName }` );
    return null;
  });
  ready.finally( () =>
  {
    if( error )
    throw _.err( error );
    return true;
  });

  return ready;

  /* */

  function srcRepositoryPrepare()
  {
    if( srcBasePathIsRepository )
    {
      ready.then( () => _.git.repositoryClone({ localPath : tempPath, remotePath : normalized }) );
    }
    else
    {
      ready.then( () => _.fileProvider.filesReflect({ dst : tempPath, src : srcBasePath }) );
      ready.then( () => _.git.repositoryInit({ localPath : tempPath, remote : 0, local : 1 }) );
      ready.then( () =>
      {
        return shell
        ({
          currentPath : tempPath,
          execPath : [ 'git add .', 'git commit -m Init', 'git commit --allow-empty -m "Indexed"' ]
        });
      });
    }
    if( srcState )
    ready.then( () => shell({ currentPath : tempPath, execPath : `git reset --hard ${ srcState }` }) );
    return ready;
  }

  /* */

  function filesFilter( msg )
  {
    if( o.srcDirPath )
    {
      _.assert( !_.git.path.isGlob( o.srcDirPath ) );
      let srcDirPath = o.srcDirPath;
      if( _.git.path.isAbsolute( o.srcDirPath ) )
      {
        srcDirPath = _.git.path.relative( srcBasePath, srcDirPath );
        _.assert( !_.git.path.isDotted( srcDirPath ) );
      }

      if( o.only )
      o.only = _.array.as( o.only );
      else
      o.only = _.array.make( 0 );

      if( o.only.length )
      for( let i = 0 ; i < o.only.length ; i++ )
      o.only[ i ] = _.git.path.join( srcDirPath, o.only[ i ] );
      else
      o.only.push( _.git.path.join( srcDirPath, '**' ) );
    }

    let pathsFromStatus;
    if( o.only || o.but )
    pathsFromStatus = pathsProduceFromMessage( msg, o.only );

    if( o.only )
    {
      const paths = pathsFilter( pathsFromStatus, o.only );
      const exclude = _.arrayAppendArray( null, pathsFromStatus );
      _.arrayRemovedArrayOnce( exclude, paths );
      if( exclude.length )
      filesUnstage( exclude );
      pathsFromStatus = paths;
    }
    if( o.but )
    {
      const exclude = pathsFilter( pathsFromStatus, o.but );
      if( exclude.length )
      filesUnstage( exclude );
      _.arrayRemovedArrayOnce( pathsFromStatus, exclude );
    }
    return pathsFromStatus;
  }

  /* */

  function pathsProduceFromMessage( msg )
  {
    const files = msg.split( '\n' );
    files.splice( 0, 1 );
    _.arrayRemoveOnce( files, '' );
    for( let i = 0 ; i < files.length ; i++ )
    files[ i ] = _.str.remove( files[ i ], /^\s*\w+\s+/ );
    return files;
  }

  /* */

  function pathsFilter( paths, selectors )
  {
    selectors = _.array.as( selectors );
    const result = _.array.make();
    for( let i = 0 ; i < selectors.length ; i++ )
    {
      const selector = _.str.removeBegin( selectors[ i ], './' );
      const entries = _.path.globShortFilter({ src : paths, selector });
      _.arrayAppendArrayOnce( result, entries );
    }
    return result;
  }

  /* */

  function filesUnstage( exclude )
  {
    shell({ execPath : `git restore --staged ${ exclude.join( ' ' ) }`, sync : 1 });
    shell({ execPath : `git clean -df`, sync : 1 });
    shell({ execPath : `git checkout ./`, sync : 1 });
  }
}

repositoryAgree.defaults =
{
  srcBasePath : null,
  dstBasePath : null,
  srcState : null,
  dstBranch : null,
  srcDirPath : null,
  dstDirPath : null,
  commitMessage : null,
  mergeStrategy : 'src', /* can be any of [ 'src', 'dst', 'manual' ] */
  relative : 'commit',
  delta : null,
  but : null,
  only : null,
  logger : 0,
  dry : 0,
};

//

function repositoryMigrate( o )
{
  _.routine.options_( repositoryMigrate, o );
  _.assert( arguments.length === 1, 'Expects single argument' );
  _.assert( _.str.defined( o.dstBasePath ), 'Expects local path to destination repository {-o.dstBasePath-}.' );
  _.assert( _.str.defined( o.srcBasePath ) || _.aux.is( o.srcBasePath ), 'Expects path to source repository {-o.srcBasePath-}.' );

  /* */

  let error = null;
  const ready = _.take( null );

  let basePath = o.dstBasePath;
  o.dstBasePath = _tagStrip( basePath );
  if( o.dstDirPath )
  basePath = _.git.path.join( o.dstBasePath, o.dstDirPath );
  basePath = _.git.path.detrail( _tagStrip( basePath ) );
  let shouldRemove = false;

  const logger = _.logger.relativeMaybe( o.logger, -1 );
  const shell = _.process.starter
  ({
    logger,
    currentPath : basePath,
    outputCollecting : 0,
    inputMirroring : 0,
  });

  if( basePath !== o.dstBasePath )
  {
    ready.then( () => _subrepositoryInitMaybe( o.dstBasePath, basePath ) );
    ready.then( ( isSubrepository ) => shouldRemove = !isSubrepository );
  }
  ready.then( () =>
  {
    if( !o.dstBranch )
    o.dstBranch = _branchFromPath( basePath, o.dstBasePath, true ) || _.git.tagLocalRetrive({ localPath : basePath });
    _.sure
    (
      _.str.defined( o.dstBranch ),
      'Expects defined branch in destination repository. Provide it by option {-o.dstBranch-} or in path.'
    );
    return null;
  });

  const normalized = _.git.path.normalize( o.srcBasePath );
  const srcBasePath = _.git.path.nativize( normalized );
  if( !o.srcBranch )
  o.srcBranch =
  _branchFromPath( basePath, normalized, false ) || _.git.tagLocalRetrive({ localPath : _.git.path.nativize( normalized ) });

  let srcState1 = o.srcState1;
  let srcState2 = o.srcState2;
  if( o.srcState1 )
  srcState1 = _.git._stateParse( o.srcState1 ).value;
  _.assert( _.str.defined( srcState1 ), 'Expects state {-o.srcState1-} to start with.' );
  if( o.srcState2 )
  srcState2 = _.git._stateParse( o.srcState2 ).value;

  if( !o.onCommitMessage )
  if( !o.editMessage )
  o.onCommitMessage = ( e ) => e;
  if( o.editMessage )
  {
    _.assert( !o.onCommitMessage, 'Expects manual or automated commit message editing, but not both.' );
    o.onCommitMessage = onCommitData_functor();
  }
  if( _.str.is( o.onCommitMessage ) )
  {
    let msg = o.onCommitMessage;
    o.onCommitMessage = ( e ) => msg;
  }
  _.assert( _.routine.is( o.onCommitMessage ), 'Expects routine to produce commit message {-o.onCommitMessage-}.' );

  if( o.onDate === null )
  if( !o.editDate )
  o.onDate = ( e ) => e;
  if( o.editDate )
  {
    _.assert( !o.onDate, 'Expects manual or automated commit date editing, but not both.' );
    o.onCommitMessage = onCommitData_functor();
  }
  if( _.aux.is( o.onDate ) )
  o.onDate = _.git._onDate_functor( o.onDate );
  _.assert( _.routine.is( o.onDate ), 'Expects routine to produce commit date {-o.onDate-}.' );

  let remoteName;
  ready.then( () => _remoteNameGenerate( basePath ) )
  ready.then( ( name ) => { remoteName = name; return null });

  ready.then( () => shell( `git remote add ${ remoteName } ${ srcBasePath }` ) );
  ready.then( () => _.git.tagLocalChange({ localPath : basePath, tag : o.dstBranch }) );
  ready.then( () => shell({ execPath : `git fetch ${ remoteName }`, outputPiping : 0 }) );
  verifyRepositoriesHasSameFiles()

  let commitsArray = [];
  ready.then( () =>
  {
    return _.git.repositoryHistoryToJson
    ({
      localPath : basePath,
      state1 : o.srcState1,
      state2 : o.srcState2 || `!${ remoteName }/${ o.srcBranch }`,
    });
  });
  if( logger )
  ready.then( ( commits ) =>
  {
    logger.log( 'List of commits to migrate :' );
    logger.log( _.entity.exportJson( commits ) );
    return commits;
  });

  if( !o.dry )
  {
    ready.then( ( commits ) =>
    {
      commitsArray = commits;
      return _.git.repositoryHistoryToJson
      ({
        localPath : o.dstBasePath,
        state1 : '#HEAD',
        state2 : '#HEAD',
      });
    });
    ready.then( ( head ) => writeCommits( head, commitsArray ) );
  }
  ready.finally( ( err, arg ) =>
  {
    if( err )
    {
      _.error.attend( err );
      error = err;
    }
    delete process.env.GIT_COMMITTER_DATE;
    if( shouldRemove )
    {
      _.fileProvider.filesDelete( _.git.path.join( basePath, '.git' ) );
      return null;
    }
    else
    {
      return shell( `git remote remove ${ remoteName }` );
    }
  });
  ready.finally( () =>
  {
    if( error )
    throw _.err( error );
    return true;
  });

  return ready;

  /* */

  function remoteNameGenerate()
  {
    ready.then( () =>
    {
      let remoteName = `_temp-${ _.idWithGuid() }`;
      const config = _.git.configRead( basePath );
      while( `remote "${ remoteName }"` in config )
      remoteName = `_temp-${ _.idWithGuid() }`;
      return remoteName;
    });
    return ready;
  }

  /* */

  function verifyRepositoriesHasSameFiles()
  {
    ready.then( () =>
    {
      return shell
      ({
        execPath : `git diff --name-only --diff-filter=d ${ o.dstBranch }..${ srcState1 }`,
        outputCollecting : 1,
      });
    });
    ready.then( ( diff ) =>
    {
      if( diff && diff.output )
      {
        const files = outputDiffPathsFilter( diff.output, false );
        if( files.length )
        throw _.err
        (
          `Expects no diffs between ${ o.dstBranch } and ${ o.srcBasePath }.`
          + `\nPlease, synchronize states before reflecting of commits.`
        );
      }
      return null;
    });
    return ready;
  }

  /* */

  function writeCommits( head, commits )
  {
    const length = commits.length;

    const gitDir = _.git.path.join( basePath, '.git' );
    const tempGitDir = _.git.path.join( basePath, '../-git.temp' );
    let storeGitDir = () => {};
    let restoreGitDir = ( e ) => e;
    if( shouldRemove )
    {
      storeGitDir = () =>
      {
        _.fileProvider.fileRename( tempGitDir, gitDir );
      };
      restoreGitDir = ( e ) =>
      {
        _.fileProvider.fileRename( gitDir, tempGitDir );
        return e;
      };
    }

    const con = _.take( null );
    con.then( () => o.onDate( commits[ length - 1 ].date, 'date', commits[ length - 1 ] ) );
    con.then( ( startCommitDate ) =>
    {
      const headDate = Date.parse( head[ 0 ].date );
      const commitStartDate = Date.parse( startCommitDate ) || _.time.now();
      _.assert( headDate <= commitStartDate, 'New commit should be newer than last commit in branch.' );
      return null;
    });

    let commitMessage, date;
    for( let i = length - 1 ; i >= 0 ; i-- )
    {
      con.then( () =>
      {
        return shell
        ({
          execPath : `git cherry-pick --strategy=recursive -X theirs -n -m 1 ${ commits[ i ].hash }`,
          throwingExitCode : 0,
        });
      });
      con.then( ( op ) =>
      {
        if( op.exitCode !== 0 )
        return shell( `git add .` );
        return null;
      });
      con.then( () => shell({ execPath : `git diff --name-only HEAD`, outputCollecting : 1, outputPiping : 0 }) );
      con.then( ( diff ) =>
      {
        if( diff.output )
        if( !_.str.begins( commits[ i ].message, 'Merge pull request' ) )
        {
          if( !outputDiffPathsFilter( diff.output, true ).length )
          return null;

          let dateCon = o.onDate( commits[ i ].date, 'date', commits[ i ] );
          let commitMessageCon = o.onCommitMessage( commits[ i ].message, 'message', commits[ i ] );
          return _.Consequence.And( dateCon, commitMessageCon );
        }
        return null;
      });
      con.then( ( commitData ) =>
      {
        if( commitData )
        {
          _.assert( _.str.is( commitData[ 0 ] ), 'Callback {-o.onDate-} should return string date.' );
          date = commitData[ 0 ].length > 0 ? `--date="${ commitData[ 0 ] }"` : '';
          commitMessage = commitData[ 1 ];
          process.env.GIT_COMMITTER_DATE = commitData[ 0 ] || '';
          return _statusLocalGet( basePath );
        }
        return null;
      });
      con.then( ( status ) =>
      {
        if( status && status.uncommitted )
        {
          const con2 = _.take( null );
          con2.then( () =>
          {
            storeGitDir();
            return null;
          });
          con2.then( () => shell({ currentPath : o.dstBasePath, execPath : `git add .` }) );
          con2.then( () => _statusLocalGet( o.dstBasePath ) );
          con2.then( ( status ) =>
          {
            if( status && status.uncommitted )
            return shell
            ({
              currentPath : o.dstBasePath,
              execPath : `git commit -m "${ commitMessage }" ${ date }`,
              outputPiping : 0
            });
            return null;
          });
          con2.then( () =>
          {
            restoreGitDir();
            return null;
          });
          return con2;
        }
        return null;
      });
    }

    return con;
  }

  /* */

  function outputDiffPathsFilter( output, unstage )
  {
    let pathsFromStatus = pathsProduceFromMessage( output );
    _.arrayRemoveOnce( pathsFromStatus, '' );

    if( o.srcDirPath )
    {
      _.assert( !_.git.path.isGlob( o.srcDirPath ) );
      let srcDirPath = o.srcDirPath;
      if( _.git.path.isAbsolute( o.srcDirPath ) )
      {
        srcDirPath = _.git.path.relative( srcBasePath, srcDirPath );
        _.assert( !_.git.path.isDotted( srcDirPath ) );
      }

      if( o.only )
      o.only = _.array.as( o.only );
      else
      o.only = _.array.make( 0 );

      if( o.only.length )
      for( let i = 0 ; i < o.only.length ; i++ )
      o.only[ i ] = _.git.path.join( srcDirPath, o.only[ i ] );
      else
      o.only.push( _.git.path.join( srcDirPath, '**' ) );
    }

    if( o.only )
    {
      let paths = pathsFilter( pathsFromStatus, o.only );
      let exclude = _.arrayAppendArray( null, pathsFromStatus );
      _.arrayRemovedArrayOnce( exclude, paths );
      if( unstage && exclude.length )
      filesUnstage( exclude );
      pathsFromStatus = paths;
    }
    if( o.but )
    {
      let exclude = pathsFilter( pathsFromStatus, o.but );
      if( unstage && exclude.length )
      filesUnstage( exclude );
      _.arrayRemovedArrayOnce( pathsFromStatus, exclude );
    }

    return pathsFromStatus;
  }

  /* */

  function pathsProduceFromMessage( msg )
  {
    const files = msg.split( '\n' );
    for( let i = 0 ; i < files.length ; i++ )
    files[ i ] = _.str.remove( files[ i ], /^\s*\w+\s+/ );
    return files;
  }

  /* */

  function pathsFilter( paths, selectors )
  {
    selectors = _.array.as( selectors );
    const result = _.array.make();
    for( let i = 0 ; i < selectors.length ; i++ )
    {
      const selector = _.str.removeBegin( selectors[ i ], './' );
      const filtered = _.path.globShortFilter({ src : paths, selector });
      _.arrayAppendArrayOnce( result, filtered );
    }
    return result;
  }

  /* */

  function filesUnstage( exclude )
  {
    shell({ execPath : `git restore --staged ${ exclude.join( ' ' ) }`, sync : 1 });
    shell({ execPath : `git clean -df`, sync : 1 });
    shell({ execPath : `git checkout ./`, sync : 1 });
  }

  /* */

  function onCommitData_functor()
  {
    const Prompt = require( 'prompts' );
    const localLogger = logger ? logger : console;

    /* */

    return async function onCommitData( value, key )
    {
      localLogger.log( `Current commit ${ key } : "${ value }".` );
      const response = await Prompt
      ({
        type : 'text',
        name : 'data',
        message : `Please, input new ${ key } :`,
      });

      return response.data || value;
    }
  }
}

repositoryMigrate.defaults =
{
  srcBasePath : null,
  dstBasePath : null,
  srcState1 : null,
  srcState2 : null,
  srcBranch : null,
  dstBranch : null,
  srcDirPath : null,
  dstDirPath : null,
  but : null,
  only : null,

  onCommitMessage : null,
  onDate : null,
  editMessage : 0,
  editDate : 0,

  logger : 0,
  dry : 0,
};

//

function repositoryHistoryToJson( o )
{
  _.assert( arguments.length === 1, 'Expects single argument.' );
  _.routine.options( repositoryHistoryToJson, o );
  _.assert( _.str.defined( o.localPath ) );

  let state1 = _.git._stateParse( o.state1 ).value;
  let state2 = _.git._stateParse( o.state2 ).value;

  const format =
  '{%n'
  + '  \\"author\\" : \\"%an\\",%n'
  + '  \\"email\\" : \\"%ae\\",%n'
  + '  \\"hash\\" : \\"%H\\",%n'
  + '  \\"message\\" : \\"%s\\",%n'
  + `  \\"date\\" : \\"%ai\\",%n`
  + `  \\"commiterDate\\" : \\"%ci\\"%n`
  + '},';

  return _.process.start
  ({
    currentPath : o.localPath,
    execPath : `git log ${ state1 }~..${ state2 } --format="${ format }"`,
    outputCollecting : 1,
    throwingExitCode : 1,
    inputMirroring : 0,
    outputPiping : 0,
  })
  .then( ( log ) =>
  {
    let commits = log.output;
    if( process.platform === 'win32' )
    commits = _.str.replace( commits, /\\/, '\\\\' );
    commits = _.str.replaceBegin( commits, '', '[\n' );
    commits = _.str.replaceEnd( commits, ',\n', '\n]' );
    return JSON.parse( commits );
  });
}

repositoryHistoryToJson.defaults =
{
  localPath : null,
  state1 : null,
  state2 : null,
};

// --
// config
// --

function configRead( filePath )
{
  const fileProvider = _.fileProvider;
  const path = _.git.path;
  // const path = fileProvider.path;

  _.assert( arguments.length === 1 );
  _.assert( _.strIs( filePath ) );

  let configPath = path.join( filePath, '.git/config' );

  if( !fileProvider.fileExists( configPath ) )
  return null;

  if( !Ini )
  Ini = require( 'ini' );

  let read = fileProvider.fileRead( configPath );
  let config = Ini.parse( read );

  return config;
}

//

function configSave( filePath, config )
{
  const fileProvider = _.fileProvider;
  const path = _.git.path;
  // const path = fileProvider.path;

  _.assert( arguments.length === 2 );
  _.assert( _.strDefined( filePath ) );
  _.assert( _.object.isBasic( config ) );

  if( !Ini )
  Ini = require( 'ini' );

  let data = Ini.stringify( config, { whitespace : true } );
  fileProvider.fileWrite( path.join( filePath, '.git/config' ), data );
}

//

function configReset( o ) /* aaa : implement */ /* Dmytro : implemented */
{
  _.assert( arguments.length === 1, 'Expects single options map {-o-}' );
  _.routine.options_( configReset, o );
  if( o.preset === 'recommended' )
  {
    _.assert( _.strDefined( o.userName ), 'Expects user name {-o.userName-}' );
    _.assert( _.strDefined( o.userMail ), 'Expects user email {-o.userMail-}' );
  }
  else
  {
    _.assert( o.preset === 'standard' );
  }

  /* */

  const ready = _.take( null );
  const start = _.process.starter
  ({
    currentPath : o.localPath,
    mode : 'shell',
    outputCollecting : 1,
    throwingExitCode : 1,
    inputMirroring : 0,
    sync : 0,
    ready,
  });

  /* */

  if( o.withLocal )
  {
    _.assert( _.git.isRepository({ localPath : o.localPath }), 'Expects git repository' );

    stadardLocalConfigSet();
    if( o.preset === 'recommended' )
    recommendedConfigSet( 'local' );
  }

  if( o.withGlobal )
  {
    standardGlobalConfigSet();
    if( o.preset === 'recommended' )
    recommendedConfigSet( 'global' );
  }

  ready.catch( ( err ) =>
  {
    _.errAttend( err );
    throw _.err( err );
  });

  if( o.sync )
  {
    ready.deasync();
    return ready.sync();
  }

  return ready;

  /* */

  function recommendedConfigSet( scope )
  {
    return start
    ({
      execPath :
      [
        `git config --${ scope } core.autocrlf false`,
        `git config --${ scope } core.ignorecase false`,
        `git config --${ scope } core.fileMode false`,
        `git config --${ scope } credential.helper store`,
        `git config --${ scope } user.name "${ o.userName }"`,
        `git config --${ scope } user.email "${ o.userMail }"`,
        `git config --${ scope } url."https://${ o.userName }@github.com".insteadOf "https://github.com"`,
        `git config --${ scope } url."https://${ o.userName }@bitbucket.org".insteadOf "https://bitbucket.org"`,
      ],
    });
  }

  /* */

  function stadardLocalConfigSet()
  {
    /* clean sections core and user */
    start
    ({
      throwingExitCode : 0,
      execPath :
      [
        'git config --local --remove-section core',
        'git config --local --remove-section user',
      ],
    });

    return start
    ({
      execPath :
      [
        'git config --local core.repositoryformatversion 0',
        'git config --local core.filemode true',
        'git config --local core.bare false',
        'git config --local core.logallrefupdates true',
      ],
    });
  }

  /* */

  function standardGlobalConfigSet()
  {
    const provider = _.fileProvider;
    const path = provider.path; /* Dmytro : should be provider path */

    const globalConfigPath = path.nativize( path.join( process.env.HOME, '.gitconfig' ) );
    /* by default global config has no settings */
    provider.fileWrite( globalConfigPath, '' );
  }
}

configReset.defaults =
{
  localPath : null,
  sync : 0,
  preset : 'recommended', /* [ recommended, standard ] */
  withGlobal : 0,
  withLocal : 1,
  userName : null,
  userMail : null,
};

//

/* qqq : implement routine to find out does exist version/tag */
/* qqq : implement routine to convert one kind of version/tag to one another */

/* qqq : aaa:fixed

 = Message of Error#1
    Unexpected change type: "u", filePath: "revision" fatal: ambiguous argument 'alhpa': unknown revision or path not in the working tree.
    Use '--' to separate paths from revisions, like this:
    'git <command> [<revision>...] -- [<file>...]'

 = Beautified calls stack
    at detailingHandle (/pro/builder/proto/wtools/amid/l3/git/l1/Tools.s:3556:15)
    at wConsequence.handleOutput (/pro/builder/proto/wtools/amid/l3/git/l1/Tools.s:3505:5)

*/

function _stateParse( state )
{
  let statesBegin = [ '#', '!' ];
  let statesSpecial = [ 'working', 'staging', 'committed' ];
  /*
  https://neurathsboat.blog/post/git-intro/
  https://git-scm.com/book/en/v2/Getting-Started-What-is-Git%3F
  */

  let result =
  {
    original : state,
    value : state,
    isSpecial : false
  };

  /* aaa : for Dmytro : should be no such special states */ /* Dmytro : done */

  // if( _.strBegins( state, 'HEAD' ) )
  // {
  //   result.isSpecial = true;
  //   return result;
  // }

  if( _.strBegins( state, statesBegin ) )
  {
    result.isVersion = _.git.stateIsHash( state );
    result.isTag = _.git.stateIsTag( state );
    result.value = _.strRemoveBegin( state, statesBegin );

    if( !result.isTag )
    return result;

    if( _.strEnds( result.value, '/' ) )
    {
      result.isTag = false;
      result.value = _.strRemoveEnd( result.value, '/' );
    }
    else if( _.strHas( result.value, '/' ) )
    {
      result.isRemoteTag = true;
      let r = _.strIsolateLeftOrNone( result.value, '/' );
      _.sure
      (
        _.strDefined( r[ 0 ] ) && _.strDefined( r[ 2 ] ),
        `Failed to parse state: ${result.original}, expects remote tag in format: "!remote/tag".`
      );
      result.remotePath = `:///${r[ 0 ]}`;
      result.remote = `!${r[ 2 ]}`;
    }

    return result;
  }

  if( !_.longHas( statesSpecial, state ) )
  throw _.err( `Expects one of special states: ${statesSpecial}, but got: ${state}` );

  result.isSpecial = true;

  return result;
}

//

function diff( o )
{
  let self = this;

  o = _.routine.options_( diff, o );

  _.assert( arguments.length === 1 );
  _.assert( _.strDefined( o.state1 ) || o.state1 === null );
  _.assert( _.strDefined( o.state2 ) );
  _.assert( _.strDefined( o.localPath ) );
  _.assert( o.linesOfContext === null || _.numberIs( o.linesOfContext ) );

  if( o.state1 === null ) /* qqq : discuss */
  o.state1 = 'HEAD';

  let ready = _.take( null );
  let result = Object.create( null );
  let state1 = self._stateParse( o.state1 );
  let state2 = self._stateParse( o.state2 ); /* qqq : ! aaa: special tags now work in both states */

  let start = _.process.starter
  ({
    sync : 0,
    deasync : 0,
    outputCollecting : 1,
    mode : 'spawn',
    currentPath : o.localPath,
    throwingExitCode : 0,
    inputMirroring : 0,
    outputPiping : 0,
    ready
  });

  if( o.fetchTags )
  start( `git fetch --tags` )

  ready.then( checkStates );
  ready.then( runDiff );
  ready.then( handleResult );

  if( o.sync )
  {
    ready.deasync();
    return ready.sync();
  }

  return ready;

  /* - */

  function checkStates()
  {
    let ready = _.take( null )
    ready.then( () => checkState( state1 ) )
    ready.then( () => checkState( state2 ) )
    ready.then( () =>
    {
      if( !o.throwingDoesNotExist )
      return null;

      if( !state1.exists )
      throw _.err( `State::${state1.original} {-o.state1-} doesn't exist in repository at ${o.localPath}` );

      if( !state2.exists )
      throw _.err( `State::${state2.original} {-o.state2-} doesn't exist in repository at ${o.localPath}` );

      return null;
    })
    return ready;
  }

  /* - */

  function checkState( state )
  {
    state.exists = true;

    if( state.isSpecial )
    return null;

    let con = _.take( null )

    if( state.isVersion || state.isTag )
    {
      let o2 =
      {
        localPath : o.localPath,
        remotePath : null,
        local : 0,
        remote : 0,
        sync : o.sync,
      }

      if( state.isRemoteTag )
      {
        o2.remotePath = state.remotePath;
        o2.remote = state.remote;
        o2.returnVersion = true;
      }
      else
      {
        o2.local = state.original;
      }

      con.then( () => self.exists( o2 ) );
    }
    else
    {
      start({ execPath : `git rev-parse ${state.value}`, ready : con })
    }

    con.then( ( got ) =>
    {
      if( _.boolIs( got ) )
      state.exists = got;
      else if( _.object.isBasic( got ) )
      state.exists = got.exitCode === 0;
      else
      {
        _.assert( _.strDefined( got ) );
        state.value = got;
        state.exists = true;
      }

      return null;
    })

    return con;
  }

  /* - */

  function runDiff()
  {
    if( !state1.exists || !state2.exists )
    return null;

    if( state1.isSpecial && state2.isSpecial )
    if( state1.value === state2.value )
    {
      result.status = o.explaining ? '' : false;
      return null;
    }

    let ready = _.take( null );

    let op =
    {
      execPath : 'git',
      ready
    }

    diffArgsForm();

    start( op )

    ready.then( handleOutput );

    return ready;

    /* */

    function diffArgsForm()
    {
      op.args = [ 'diff', '--exit-code' ]

      if( o.detailing )
      op.args.push( '--raw' )
      else
      op.args.push( '--stat' )

      if( o.generatingPatch )
      op.args.push( '--patch' )

      if( _.numberIs( o.linesOfContext ) )
      op.args.push( `--unified=${o.linesOfContext}` )

      if( o.coloredPatch )
      op.args.push( '--color=always' )
      else
      op.args.push( '--color=never' )

      argsForStateForm( state1 );
      argsForStateForm( state2 );
    }

    /* */

    function argsForStateForm( state )
    {
      if( !state.isSpecial )
      op.args.push( state.value );
      else if( state.value === 'staging' )
      op.args.push( '--staged' )
      else if( state.value === 'committed' )
      op.args.push( 'HEAD' )
      else if( _.strBegins( state.value, 'HEAD' ) )
      op.args.push( state.value );
    }

    /*
    if( state1.value === 'working' )
    start({ execPath : `git diff ${diffMode} --exit-code ${state2.value}`, ready })
    else if( state1.value === 'staging' )
    start({ execPath : `git diff --staged ${diffMode} --exit-code ${state2.value}`, ready })
    else if( state1.value === 'committed' )
    start({ execPath : `git diff ${diffMode} --exit-code HEAD ${state2.value}`, ready })
    else
    start({ execPath : `git diff ${diffMode} --exit-code ${state1.value} ${state2.value}`, ready }) */
  }

  /*  */

  function handleOutput( got )
  {
    result.modifiedFiles = '';
    result.deletedFiles = '';
    result.addedFiles = '';
    result.renamedFiles = '';
    result.copiedFiles = '';
    result.typechangedFiles = '';
    result.unmergedFiles = '';

    let status = '';

    if( o.detailing )
    detailingHandle( got );

    for( var k in result )
    {
      if( !o.detailing )
      result[ k ] = got.exitCode === 1 ? _.maybe : false;
      else if( !o.explaining )
      result[ k ] = !!result[ k ];
      else if( result[ k ] )
      {
        _.assert( _.strDefined( result[ k ] ) );
        status += status ? '\n' + k : k;
        status += ':\n  ' + _.strLinesIndentation( result[ k ], '  ' );
      }
    }

    if( o.generatingPatch )
    result.patch = got.output;

    if( o.explaining && !o.detailing )
    status = got.output;

    result.status = o.explaining ? status : got.exitCode === 1;

    return result;
  }

  /*  */

  function detailingHandle( got )
  {
    let statusToPropertyMap =
    {
      'A' : 'addedFiles',
      // 'C' : 'copiedFiles',
      'C' : 'copiedFiles', /* aaa : ? */ /* Dmytro : fixed, not me, the task resolved in conversation */
      'D' : 'deletedFiles',
      'M' : 'modifiedFiles',
      'R' : 'renamedFiles',
      'T' : 'typechangedFiles',
      'U' : 'unmergedFiles',
    }
    let lines = _.strSplitNonPreserving
    ({
      src : got.output,
      delimeter : '\n',
      stripping : 1,
      preservingEmpty : 1,
    });
    let endOfRawOutput = _.longLeftIndex( lines, '' );
    endOfRawOutput = endOfRawOutput >= 0 ? endOfRawOutput : lines.length;

    for( let i = 0; i < endOfRawOutput; i++ )
    {
      lines[ i ] = _.strSplitNonPreserving({ src : lines[ i ], delimeter : /\s+/, stripping : 1 })
      let type = lines[ i ][ 4 ].charAt( 0 );
      let path = lines[ i ][ 5 ];
      let pName = statusToPropertyMap[ type ];
      if( !pName )
      throw _.err( `Unexpected change type: ${_.strQuote( type )}, filePath: ${_.strQuote( path )}`, got.output );
      if( o.explaining )
      result[ pName ] += result[ pName ] ? '\n' + path : path;
      else
      result[ pName ] = true;
    }
  }

  /* - */

  function handleResult()
  {
    result.state1 = state1;
    result.state2 = state2;
    if( !state1.exists || !state2.exists )
    result.status = _.maybe;
    return result;
  }
}

diff.defaults =
{
  state1 : 'working',
  state2 : 'committed',
  localPath : null,
  detailing : 1,
  explaining : 1,
  generatingPatch : 0, // https://git-scm.com/docs/git-diff.html#Documentation/git-diff.txt---patch
  throwingDoesNotExist : 0,
  linesOfContext : null, // https://git-scm.com/docs/git-diff.html#Documentation/git-diff.txt---unifiedltngt
  coloredPatch : 0, // https://git-scm.com/docs/git-diff.html#Documentation/git-diff.txt---colorltwhengt
  fetchTags : 0,
  sync : 1
}

//

function pull( o )
{
  let ready = _.take( null );

  _.assert( arguments.length === 1 );
  _.routine.options_( pull, arguments );
  _.assert( _.strDefined( o.localPath ) );

  if( o.dry )
  return;

  let start = _.process.starter
  ({
    sync : 0,
    deasync : 0,
    outputCollecting : 1,
    mode : 'shell',
    currentPath : o.localPath,
    throwingExitCode : o.throwing,
    inputMirroring : 1,
    outputPiping : 1,
    logger : o.logger,
    ready,
  });

  start( `git pull` );

  if( o.sync )
  {
    ready.deasync();
    return ready.sync();
  }
  return ready;
}

pull.defaults =
{
  localPath : null,
  dry : 0,
  sync : 1,
  logger : null,
  throwing : 0,
};

//

function push( o )
{
  _.assert( arguments.length === 1 );
  _.routine.options_( push, arguments );
  _.assert( _.strDefined( o.localPath ) );

  let ready = _.take( null );

  let start = _.process.starter
  ({
    sync : 0,
    deasync : 0,
    outputCollecting : 1,
    mode : 'shell',
    currentPath : o.localPath,
    throwingExitCode : o.throwing,
    inputMirroring : 1,
    outputPiping : 1,
    logger : o.logger,
    ready,
  });

  let dryRun = o.dry ? ' --dry-run' : '';
  let force = o.force ? ' --force' : '';

  if( o.withHistory )
  start( `git push ${ dryRun } -u origin --all ${ force }` );
  if( o.withTags )
  {
    verifyRemoteRepositoryHasCommitHistory();
    if( !o.force )
    verifyRemoteRepositoryHasNoTag();
    start( `git push ${ dryRun } --tags ${ force }` );
  }

  if( o.sync )
  {
    ready.deasync();
    return ready.sync();
  }
  return ready;

  /* */

  function verifyRemoteRepositoryHasCommitHistory()
  {
    let unpushedTags = tagsUnpushedGet();

    if( unpushedTags.length === 0 )
    return true;

    let commits = tagsCommitsGet( unpushedTags );

    if( _.any( commits, remoteCommitNotExists ) )
    throw _.err
    (
      `Repository at ${ o.localPath } has different commit history on remote server. `,
      `Please, push history manually or enable option {-o.withHistory-}`
    );
    return true;
  }

  /* */

  function tagsUnpushedGet()
  {
    let output = start
    ({
      execPath : 'git push --tags --dry-run',
      sync : 1,
      outputPiping : 0,
      inputMirroring : 0,
      throwingExitCode : 0,
    }).output;
    let tags = output.match( /(\S+)\s->/gm );
    if( !tags )
    return [];
    for( let i = 0 ; i < tags.length ; i++ )
    tags[ i ] = tags[ i ].split( ' ' )[ 0 ];
    return tags;
  }

  /* */

  function tagsCommitsGet( tags )
  {
    let result = _.array.make( tags );
    for( let i = 0 ; i < tags.length ; i++ )
    {
      let commit = start({ execPath : `git show-ref -s ${ tags[ i ] }`, sync : 1 }).output;
      result[ i ] = commit.trim();
    }
    return result;
  }

  /* */

  function remoteCommitNotExists( commit )
  {
    let exists =_.git.repositoryHasVersion
    ({
      localPath : o.localPath,
      version : commit.trim(),
      local : 0,
      remote : 1,
    });
    return !exists;
  }

  /* */

  function verifyRemoteRepositoryHasNoTag()
  {
    let currentTag = start({ execPath : 'git describe --abbrev=0 --tags', sync : 1 }).output;
    let repoHasTag = _.git.repositoryHasTag
    ({
      localPath : o.localPath,
      tag : currentTag.trim(),
      local : 0,
      remote : 1,
    });

    if( repoHasTag )
    throw _.err
    (
      `Remote repository of ${ o.localPath } has the same tags as local repository.`,
      `Please, push tags manually or enable option {-o.force-} to rewrite tags`
    );

    return true;
  }
}

push.defaults =
{
  localPath : null,
  withHistory : 1,
  withTags : 0,
  force : 0,
  dry : 0,
  sync : 1,
  throwing : 0,
  logger : null
};

//

function reset_head( routine, args )
{
  _.assert( arguments.length === 2 );

  let o = args[ 0 ];
  _.assert( args.length === 1 );
  _.routine.options( routine, o );
  _.assert( _.strDefined( o.state1 ) );
  _.assert( _.strDefined( o.state2 ) );
  _.assert( _.strDefined( o.localPath ) );
  _.assert( _.longHas( [ null, 'all' ], o.preset ) );

  o.logger = _.logger.maybe( o.logger );

  if( o.preset === 'all' )
  {
    _.assert( o.state2 === 'committed', 'Preset `all` resets all changes to latest commit' );

    let o2 =
    {
      removingUntracked : 1,
      removingSubrepositories : 1,
      removingIgnored : 1,
    };
    _.mapSupplementNulls( o, o2 );
  }
  else
  {
    let o2 =
    {
      removingUntracked : 1,
      removingSubrepositories : 1,
      removingIgnored : 0,
    };
    _.mapSupplementNulls( o, o2 );
  }
  return o;
}

//

/* aaa : for Dmytro : use _.routine.unite */ /* Dmytro : done */

function reset_body( o )
{
  let self = this;

  // _.assert( arguments.length === 1 );
  // _.routineOptions( reset, arguments );
  // _.assert( _.strDefined( o.state1 ) );
  // _.assert( _.strDefined( o.state2 ) );
  // _.assert( _.strDefined( o.localPath ) );
  // _.assert( _.longHas( [ null, 'all' ], o.preset ) );
  //
  // o.logger = _.logger.maybe( o.logger );
  //
  // if( o.preset === 'all' )
  // {
  //   _.assert( o.state2 === 'committed', 'Preset `all` resets all changes to latest commit' );
  //
  //   let o2 =
  //   {
  //     removingUntracked : 1,
  //     removingSubrepositories : 1,
  //     removingIgnored : 1,
  //   };
  //   // _.mapExtend( o, o2 ); /* aaa : for Dmytro : should supplement */ /* Dmytro : done */
  //   _.mapSupplement( o, o2 );
  // }

  /* */

  let ready = _.take( null );

  let start = _.process.starter
  ({
    sync : 0,
    deasync : 0,
    outputCollecting : 1,
    mode : 'shell',
    currentPath : o.localPath,
    throwingExitCode : 0,
    inputMirroring : 0,
    outputPiping : 0,
    logger : o.logger,
    ready
  });

  /* */

  let state1 = self._stateParse( o.state1 );
  let state2 = self._stateParse( o.state2 );

  if( o.dry )
  return resetDry();

  if( state2.value === 'working' || state2.value === 'staged' )
  return;

  /* */

  let commands = [];

  if( state1.isVersion || state1.isTag )
  commands.push( `git checkout ${ state1.value }` );
  // start( `git checkout ${ state1.value }` );
  /* aaa : for Dmytro : ? */ /* Dmytro : state1 define start point for resetting. If state is not tag or hash, then repository should not change this state */

  if( state2.value === 'committed' )
  commands.push( `git reset --hard` );
  else if( state2.isVersion || state2.isTag )
  commands.push( `git reset --hard ${ state2.value }` );
  // if( state2.value === 'committed' )
  // start( `git reset --hard` );
  // else if( state2.isVersion || state2.isTag )
  // start( `git reset --hard ${ state2.value }` );

  if( o.removingUntracked )
  {
    let command = `git clean -df`
    if( o.removingSubrepositories )
    command += 'f';
    if( o.removingIgnored )
    command += 'x';

    commands.push( command );
    // start( command );
  }

  start( commands );

  /* aaa : should be "git clean -dffx", but not by default */ /* Dmytro : implemented */
  /* aaa : cover each option */ /* Dmytro : covered */

  if( o.sync )
  {
    ready.deasync();
    return ready.sync();
  }
  return ready;

  /* */

  function resetDry()
  {
    let shouldReset = state2.isVersion || state2.isTag || state2.value === 'committed';
    let o2 =
    {
      localPath : o.localPath,
      uncommitted : 0,
      uncommittedUntracked : o.removingUntracked,
      uncommittedAdded : o.removingUntracked,
      uncommittedChanged : shouldReset,
      uncommittedDeleted : shouldReset,
      uncommittedRenamed : shouldReset,
      uncommittedCopied : o.removingUntracked,
      uncommittedIgnored : o.removingUntracked && o.removingIgnored,
      unpushed : 0,
      unpushedCommits : 0,
      unpushedTags : 0,
      unpushedBranches : 0,
      explaining : 1,
      detailing : 1,
      sync : 1
    };
    let status = _.git.statusLocal( o2 );

    /* */

    let msgReset = `Uncommitted changes, would be reseted :`;
    msgReset += status.uncommittedChanged ? `\n${ status.uncommittedChanged }` : ``;
    msgReset += status.uncommittedDeleted ? `\n${ status.uncommittedDeleted }` : ``;
    msgReset += status.uncommittedRenamed ? `\n${ status.uncommittedRenamed }` : ``;
    o.logger.log( msgReset );

    let msgClean = `Uncommitted changes, would be cleaned :`;
    msgClean += status.uncommittedUntracked ? `\n${ status.uncommittedUntracked }` : ``;
    msgClean += status.uncommittedAdded ? `\n${ status.uncommittedAdded }` : ``;
    msgClean += status.uncommittedCopied ? `\n${ status.uncommittedCopied }` : ``;
    msgClean += status.uncommittedIgnored ? `\n${ status.uncommittedIgnored }` : ``;
    o.logger.log( msgClean );
    return true;
  }
}

reset_body.defaults =
{
  // logger : 1,
  state1 : 'working', /* 'working', 'staged', 'committed' some commit or tag */
  state2 : 'committed', /* 'working', 'staged', 'committed' some commit or tag */
  localPath : null,
  preset : null, /*[ null, 'all' ]*/ /* aaa : implement and cover option */ /* Dmytro : implemented, preset supplement options in reset_head */
  // removingUntracked : 1,
  // removingIgnored : 0, /* aaa : implement and cover option */ /* Dmytro : implemented, covered */
  // removingSubrepositories : 1, /* aaa : implement and cover option. option -ffx of git command clean */ /* Dmytro : implemented, covered */
  removingUntracked : null,
  removingIgnored : null,
  removingSubrepositories : null,
  dry : 0, /* aaa : implement and cover option */ /* Dmytro : implemented, covered */
  sync : 1,
  logger : null
};

