const reset = _.routine.unite( reset_head, reset_body );

//

let millisecondsConvert = null;

function _getDelta( src )
{
  if( _.number.is( src ) )
  return src;

  const negative = _.str.begins( src, '-' );
  if( negative )
  src = _.str.removeBegin( src, '-' );

  let parts = src.trim().split( ':' );

  if( parts.length === 3 )
  {
    const hours = _.number.from( parts[ 0 ] );
    const days = Math.trunc( hours / 24 );
    let baseDelta = 86400000 * days;
    parts[ 0 ] = hours - ( days * 24 );
    return ( baseDelta + Date.parse( `01 Jan 1970 ${ parts.join( ':' ) } GMT` ) ) * ( negative ? -1 : 1 );
  }

  _.assert( parts.length <= 1 );

  if( millisecondsConvert === null )
  {
    const unitsBaseRatio =
    {
      default : 'ms',
      ms : 1,
      s : 1000,
      m : 60 * 1000,
      h : 60 * 60 * 1000,
      d : 24 * 60 * 60 * 1000,
    };
    millisecondsConvert = _.units.unitsConvert_functor({ unitsBaseRatio });
  }

  parts = parts[ 0 ].split( /\s+/ );
  let result = 0;
  for( let i = 0 ; i < parts.length ; i++ )
  result += millisecondsConvert({ src : parts[ i ] });
  return result * ( negative ? -1 : 1 );
}

//

function _onDate_functor( o )
{
  _.assert( arguments.length === 1 );
  _.mapSupplementNulls( o, _onDate_functor.defaults );
  _.assert
  (
    _.longHas( [ 'now', 'commit', 'fromFirst' ], o.relative ),
    () => 'Expects option {-o.relative-} with value "now" or "commit".'
  );
  _.assert( _.number.intIs( o.delta ) || _.str.is( o.delta ) );
  _.assert( _.number.intIs( o.periodic ) || _.str.is( o.periodic ) );
  _.assert( _.number.intIs( o.deviation ) || _.str.is( o.deviation ) );

  const delta = _getDelta( o.delta );

  if( o.periodic )
  {
    return onDatePeriodic_functor();
  }
  else
  {
    if( o.relative === 'now' )
    {
      if( delta === 0 )
      return dateNow;
      else
      return dateNowWithDelta;
    }

    if( o.relative === 'commit' || o.relative === 'fromFirst' )
    {
      if( delta === 0 )
      return dateCommit;
      else
      return dateCommitWithDelta;
    }
  }

  /* */

  function dateNow( date )
  {
    return new Date().toString();
  }

  /* */

  function dateCommit( date )
  {
    return date;
  }

  /* */

  function dateNowWithDelta( date )
  {
    const time = Date.now();
    const dateObject = new Date( time + delta );
    return dateObject.toString();
  }

  /* */

  function dateCommitWithDelta( date )
  {
    const time = Date.parse( date );
    const dateObject = new Date( time + delta );
    return dateObject.toString();
  }

  /* */

  function onDatePeriodic_functor()
  {
    let startTime;
    if( o.relative === 'now' )
    startTime = _.time.now() + delta;
    let counter = 0;
    const period = _getDelta( o.periodic );
    _.assert( period >= 0 );
    const deviation = _getDelta( o.deviation );
    _.assert( deviation >= 0 );
    _.assert( deviation <= period, 'Deviation cannot be bigger than period.' );

    if( o.relative === 'now' )
    return datePeriodicNow;
    if( o.relative === 'fromFirst' )
    return datePeriodicCommitStrict;
    return datePeriodicCommit;

    function datePeriodicNow( date )
    {
      let result = startTime + ( counter * period ) + ( Math.random() * 2 * deviation - deviation );
      counter++;
      return new Date( result ).toString();
    }

    function datePeriodicCommit( date )
    {
      const time = Date.parse( date ) + delta;
