let SeekingError = _.error.error_functor( 'SeekingError' );

let ContainerType =
{
  'terminal' : 0,
  'countable' : 1,
  'aux' : 2,
  'hashMap' : 3,
  'set' : 4,
  'custom' : 5,
  'last' : 5,
