    if( !o.sync || o.deasync )
    {
      o.pnd.on( 'error', handleError );
      o.pnd.on( 'close', handleClose );
      o.pnd.on( 'exit', handleExit );
      o.pnd.on( 'disconnect', handleDisconnect );
    }

  }

  /* */

  function inputMirror()
  {
