          _errAdditive = '';
        }
        else
        {
          msg = _outAdditive + _.strRemoveEnd( msg, '\n' );
          _outAdditive = '';
        }
      }
      else
      {
        /* xxx yyy qqq for junior : not implemeted yet | aaa : Implemented. */
        if( _.strHas( msg, '\n' ) )
        {
          let lastBreak = msg.lastIndexOf( '\n' );
          let left = msg.slice( lastBreak + 1 );
          msg = msg.slice( 0, lastBreak );
          if( channel === 'err' )
          _errAdditive += left;
          else
          _outAdditive += left;
        }
        else
        {
          if( channel === 'err' )
          _errAdditive += msg;
          else
          _outAdditive += msg;
          return;
        }
        // if( !_.strHas( msg, '\n' ) )
