      }
      /* qqq : for junior : bad : it cant be working */
      if( channel === 'err' )
      o.logger.error( msg );
      else
      o.logger.log( msg );
    }
    else
    {
      _decoratedOutOutput += msg;
      if( channel === 'err' )
      _decoratedErrOutput += msg;
      /* yyy qqq for junior : cover */
      // _decoratedOutOutput += msg + '\n';
      // if( channel === 'err' )
      // _decoratedErrOutput += msg + '\n';
    }

  }

