  _.assert( it.absoluteLevel === null );
  it.absoluteLevel = 0;
  _.assert( Object.hasOwnProperty.call( it.iterator, 'selector' ) );
  // _.assert( Object.hasOwnProperty.call( Object.getPrototypeOf( it ), 'selector' ) );
  return it;
}

//

function iteratorInitEnd( iterator )
{
