    //     _.assert( _.strIs( right ) );
    //
    //     while( a < splits.length-3 )
    //     {
    //       let cuts = _.strIsolateRightOrAll({ src : right, delimeter : o.entryDelimeter, quote : 1, times : 1 });
    //       if( cuts[ 1 ] === undefined )
    //       {
