      it.lines[ 0 ] = it.lines[ 0 ] || [];
      it.lines[ 0 ].push( it.cellDrawn );
      if( it.ncToken && it.i2d[ 1 ] < o.dim[ 1 ]-1 )
      it.lines[ 0 ].push( it.ncToken );
      if( it.lThinToken && it.i2d[ 1 ] < o.dim[ 1 ]-1 && colSplitHas( it.i2d[ 1 ] ) )
